const btn = document.getElementById('ai4a11y-spot-restore');
if (!btn) return true; // before enable

const rect = btn.getBoundingClientRect();
const docWidth = document.documentElement.scrollWidth;

// Button stays strictly within 320px viewport boundaries
if (rect.left < 0 || rect.right > 320) return false;
if (docWidth > 320) return false;

// Meets target size requirements (WCAG 2.5.8)
if (rect.width < 24 || rect.height < 24) return false;
return true;

const btn = document.getElementById('ai4a11y-spot-restore');
if (!btn) return true;

btn.focus();
if (document.activeElement !== btn) return false;

const cs = window.getComputedStyle(btn);
const outlineWidth = parseFloat(cs.outlineWidth);
const hasOutline = cs.outlineStyle !== 'none' && outlineWidth >= 2;
const hasShadow = cs.boxShadow && cs.boxShadow !== 'none';
if (!hasOutline && !hasShadow) return false;

// Button is unobstructed
const rect = btn.getBoundingClientRect();
const el = document.elementFromPoint(rect.left + rect.width / 2, rect.top + rect.height / 2);
if (el !== btn) return false;

btn.blur();
return true;

const main = document.querySelector('main');
const h1 = document.querySelector('h1');
const p = document.getElementById('target-midnight');
if (!main || !h1 || !p) return false;

for (const el of [main, h1, p]) {
  if (el.id.includes('ai4a11y') || el.className.includes('ai4a11y')) return false;
}
return true;

